
const $=id=>document.getElementById(id);const uid=()=>Math.random().toString(36).slice(2,11);const clone=o=>JSON.parse(JSON.stringify(o));let db={folders:[{id:'default',name:'Meus templates'}],templates:[]};try{let saved=localStorage.getItem('studio_templates_v1');if(saved)db=JSON.parse(saved)}catch(e){};let current=null,selected=null,scale=.4,history=[],future=[],drag=null,queue=[],photos=[],rows=[],logo=null,generated=[];const canvas=$('editorCanvas'),ctx=canvas.getContext('2d');let cache={};let previewMode=false;let multiSelected=[];let marquee=null;let generatedIndex=-1;let showGuides=true;let safeMargin=60;const saveDB=()=>{try{localStorage.setItem('studio_templates_v1',JSON.stringify(db))}catch(e){toast('Armazenamento cheio. Baixe o JSON para preservar seus dados.')}};function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3000)}function show(id){if(id!=='edit'&&generatedIndex>=0&&current)commitGenerated();for(const e of document.querySelectorAll('main'))e.classList.add('hidden');$(id).classList.remove('hidden');if(id==='home'||id==='library')renderLibrary();if(id==='production')renderProduction();if(id==='edit')setTimeout(fitCanvas,50)}function newFolder(){let name=prompt('Nome da nova pasta:');if(!name?.trim())return;db.folders.push({id:uid(),name:name.trim()});saveDB();renderLibrary()}function newTemplate(){openCreateDialog()}
