function snapshot(){history.push(clone(current.elements));if(history.length>60)history.shift();future=[]}function undo(){if(!history.length)return;future.push(clone(current.elements));current.elements=history.pop();selected=null;multiSelected=[];renderEditor()}function redo(){if(!future.length)return;history.push(clone(current.elements));current.elements=future.pop();selected=null;multiSelected=[];renderEditor()}function addElement(type){snapshot();let n=current.elements.filter(x=>x.type===type).length+1;let e={id:uid(),type,x:100,y:100,w:type==='text'?650:500,h:type==='text'?150:400,rotation:0,opacity:100,blend:'source-over',fill:type==='rect'?'#6559d8':'#d7dce7',text:type==='text'?'TÍTULO PRINCIPAL':'',fontSize:75,italic:false,underline:false,fontFamily:'Arial',bold:true,align:'left',binding:type==='text'?'T1':type==='logo'?'LOGO':type==='rect'?'':'IMG'+n,colorBinding:'',src:null,fit:'cover',radius:0,shape:'rectangle',blur:0,brightness:100,contrast:100};if(type==='logo'){e.w=230;e.h=130}current.elements.push(e);selected=e.id;multiSelected=[e.id];renderEditor()}function toggleTextStyle(style){let e=getSelected();if(!e||e.type!=='text')return;snapshot();e[style]=!e[style];renderEditor()}function addTemplateText(kind){addElement('text');let e=getSelected();if(kind==='T2'){Object.assign(e,{binding:'T2',text:'Subtítulo da sua arte',fontSize:46,fontFamily:'Arial',bold:false,w:760,h:160,y:300})}else{Object.assign(e,{binding:'T1',text:'TÍTULO PRINCIPAL',fontSize:96,fontFamily:'Arial Black',bold:true,w:850,h:240,y:120})}renderEditor()}
