function setProp(key,value,type){let e=getSelected();if(!e)return;e[key]=type==='number'?Number(value):value;drawEditor();if(key==='binding')renderLayers()}function duplicateSelected(){let ids=multiSelected.length?multiSelected:[selected];if(!ids.length)return;snapshot();let groupMap={},copies=[];for(let e of current.elements.filter(x=>ids.includes(x.id))){let c=clone(e);c.id=uid();c.x+=30;c.y+=30;if(c.groupId)c.groupId=groupMap[c.groupId]||(groupMap[c.groupId]=uid());c.locked=false;copies.push(c)}current.elements.push(...copies);multiSelected=copies.map(x=>x.id);selected=multiSelected[multiSelected.length-1];renderEditor()}
