canvas.addEventListener('pointermove',ev=>{let p=point(ev);if(marquee){marquee.end=p;drawEditor();return}if(!drag){let e=getSelected(),h=e&&findHandle(p,e);canvas.style.cursor=h==='rotate'?'grab':h==='nw'||h==='se'?'nwse-resize':h==='ne'||h==='sw'?'nesw-resize':h==='e'||h==='w'?'ew-resize':h==='n'||h==='s'?'ns-resize':hit(p)?'move':'default';return}let e=getSelected();if(!e)return;let dx=p.x-drag.start.x,dy=p.y-drag.start.y;if(drag.handle==='move'){for(let item of drag.moving){let target=current.elements.find(x=>x.id===item.id);if(target){target.x=item.x+dx;target.y=item.y+dy}}}else if(drag.handle==='rotate'){let cx=drag.ox+drag.ow/2,cy=drag.oy+drag.oh/2;e.rotation=Math.round((Math.atan2(p.y-cy,p.x-cx)*180/Math.PI+90)/5)*5}else{let a=-drag.rotation*Math.PI/180,lx=dx*Math.cos(a)-dy*Math.sin(a),ly=dx*Math.sin(a)+dy*Math.cos(a),h=drag.handle;let dl=h.includes('w')?lx:0,dr=h.includes('e')?lx:0,dt=h.includes('n')?ly:0,db=h.includes('s')?ly:0;let corner=(h.includes('n')||h.includes('s'))&&(h.includes('e')||h.includes('w'));if(corner){let factorX=(drag.ow+dr-dl)/Math.max(1,drag.ow),factorY=(drag.oh+db-dt)/Math.max(1,drag.oh);let factor=Math.max(.05,Math.abs(factorX-1)>Math.abs(factorY-1)?factorX:factorY);let width=drag.ow*factor,height=drag.oh*factor;dl=h.includes('w')?drag.ow-width:0;dr=h.includes('e')?width-drag.ow:0;dt=h.includes('n')?drag.oh-height:0;db=h.includes('s')?height-drag.oh:0;if(e.type==='text')e.fontSize=Math.max(8,(drag.fontSize||e.fontSize||75)*factor)}let nw=Math.max(20,drag.ow+dr-dl),nh=Math.max(20,drag.oh+db-dt);if(nw===20){if(h.includes('w'))dl=drag.ow+dr-20;else dr=20-drag.ow+dl}if(nh===20){if(h.includes('n'))dt=drag.oh+db-20;else db=20-drag.oh+dt}let cx=(dl+dr)/2,cy=(dt+db)/2,ra=drag.rotation*Math.PI/180,wx=cx*Math.cos(ra)-cy*Math.sin(ra),wy=cx*Math.sin(ra)+cy*Math.cos(ra);e.w=nw;e.h=nh;e.x=drag.ox+(drag.ow-nw)/2+wx;e.y=drag.oy+(drag.oh-nh)/2+wy}drawEditor()});
