 $('editorSaveButton').textContent=active?'✓ Guardar ajustes':'Salvar template';
 $('editorCloseButton').textContent=active?'Voltar à produção':'Fechar';
 $('editorCloseButton').onclick=active?()=>show('production'):()=>show('library');
