(()=>{const bar=document.querySelector('.workspace>.editor-top');if(!bar)return;const ids=['previewToggle','smartToggleButton','editorSaveButton','editorCloseButton'];const group=document.createElement('div');group.className='editor-main-actions';for(const id of ids){const el=document.getElementById(id);if(el)group.appendChild(el)}bar.appendChild(group);
// Remove decorative characters from static labels without injecting extra nodes.
const labels={previewToggle:'Pré-visualizar',smartToggleButton:'Ajuste inteligente',editorSaveButton:'Salvar template',editorCloseButton:'Fechar'};for(const [id,label] of Object.entries(labels)){const el=document.getElementById(id);if(el)el.textContent=label}
})();
